extra_css="""
.map select{max-width:100%;background:#edf6ed;color:#173233;padding:8px;border:0;border-radius:4px;font:inherit}.map label{display:block;margin:14px 0 5px}.map .commands{display:flex;flex-wrap:wrap;gap:8px}.map button:disabled{background:#345356;color:#d3dbd4;cursor:default}.map .halo{opacity:0}.map .candidate .halo{opacity:1}.map .pin{display:none}.map .target .pin{display:block}.map .route{stroke:#f4d77d;stroke-width:7}.map output{min-height:72px}.map text{font-size:14px}nav a[aria-current]{text-decoration:underline;text-underline-offset:6px}main{min-height:65vh}.inner{padding:48px 0}.inner>p{font-size:18px}.inner a{color:#195396}.map svg{background:radial-gradient(at 75% 55%,#234649,#122e32)}"""
